window.YOGI_DATA = {"asOf":"2026-10-18","name":"UP - The Yogi Years","period":"19 March 2017 – 18 October 2026","sources":[{"id":"S01","title":"UP Budget 2026-27: official highlights","org":"Uttar Pradesh Information Department","type":"Primary","url":"https://information.up.gov.in/admin/UploadDocument/OtherPress/compressed_12022026010930Final%20English%20Budget%202026-27.pdf"},{"id":"S02","title":"Uttar Pradesh Budget Analysis 2026-27","org":"PRS Legislative Research","type":"Independent analysis","url":"https://prsindia.org/budgets/states/uttar-pradesh-budget-analysis-2026-27"},{"id":"S03","title":"Uttar Pradesh Budget Analysis 2025-26","org":"PRS Legislative Research","type":"Independent analysis","url":"https://prsindia.org/budgets/states/uttar-pradesh-budget-analysis-2025-26"},{"id":"S04","title":"SDG India Index 2023-24","org":"NITI Aayog","type":"Primary","url":"https://www.niti.gov.in/sites/default/files/2024-07/SDA_INDIA_Publication.pdf"},{"id":"S05","title":"District SDG profiles 2023-24","org":"UP Planning Department","type":"Primary","url":"https://planning.up.nic.in/sdgcif_pdf/Reports_and_Publication/Final_District_Profile.pdf"},{"id":"S06","title":"National Multidimensional Poverty Index 2023","org":"NITI Aayog / UNDP","type":"Primary","url":"https://www.undp.org/india/publications/national-multidimensional-poverty-index-progress-review-2023"},{"id":"S07","title":"Multidimensional poverty discussion paper 2024","org":"NITI Aayog","type":"Modelled estimates","url":"https://www.niti.gov.in/sites/default/files/2024-01/MPI-22_NITI-Aayog20254.pdf"},{"id":"S08","title":"Uttar Pradesh NFHS-4 vs NFHS-5 fact sheet","org":"Ministry of Health and Family Welfare","type":"Primary survey","url":"https://www.mohfw.gov.in/sites/default/files/NFHS-5_Phase-II_0.pdf"},{"id":"S09","title":"Annual Status of Education Report 2024","org":"ASER Centre","type":"Independent survey","url":"https://asercentre.org/aser-2024/"},{"id":"S10","title":"Crime in India 2023","org":"National Crime Records Bureau / data.gov.in","type":"Primary administrative","url":"https://www.data.gov.in/catalog/crime-india-2023"},{"id":"S11","title":"Supreme Court judgment on demolition safeguards, 13 November 2024","org":"Supreme Court of India","type":"Primary judicial","url":"https://api.sci.gov.in/supremecourt/2022/12239/12239_2022_2_1501_57147_Judgement_13-Nov-2024.pdf"},{"id":"S12","title":"Profile of the 18th UP Legislative Assembly","org":"PRS Legislative Research","type":"Independent analysis","url":"https://prsindia.org/legislatures/state/vital-stats/profile-of-the-18th-uttar-pradesh-legislative-assembly"},{"id":"S13","title":"State finances audit 2023-24, tabled August 2025","org":"Comptroller and Auditor General of India","type":"Primary audit","url":"https://www.cag.gov.in/en/audit-report/details/122472"},{"id":"S14","title":"UP Investors Summit 2023 investment proposals","org":"Invest UP","type":"Government claim","url":"https://invest.up.gov.in/wp-content/uploads/2023/05/ENGLISH_PR_UP-Govt-shortlists-MoUs-worth-Rs-8-lakh-crore-for-groundbreaking-ceremony_May-18-2023.pdf"},{"id":"S15","title":"Nivesh Sarathi investment status dashboard","org":"Government of Uttar Pradesh","type":"Administrative dashboard","url":"https://niveshsarathi.up.gov.in/"},{"id":"S16","title":"Periodic Labour Force Survey reports","org":"Directorate General of Employment","type":"Primary survey","url":"https://www.dge.gov.in/reference-publication-reports-annual"},{"id":"S17","title":"Union PLFS 2023-24 release","org":"Ministry of Statistics, PIB","type":"Primary survey summary","url":"https://www.pib.gov.in/Pressreleaseshare.aspx?PRID=2057970&lang=2&reg=48"},{"id":"S18","title":"Supreme Court demolition ruling: independent report","org":"Reuters","type":"Independent reporting","url":"https://www.reuters.com/world/india/indias-top-court-denounces-demolitions-illegal-properties-issues-guidelines-2024-11-13/"},{"id":"S19","title":"Poverty: 24.82 crore estimate and UP contribution","org":"Press Information Bureau / NITI Aayog","type":"Modelled estimates","url":"https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=1996271"},{"id":"S20","title":"UP state-level and district-level SDG indicators","org":"UP Planning Department","type":"Primary","url":"https://planning.up.nic.in/"},{"id":"S21","title":"UP Budget Analysis 2026-27, sector annexure","org":"PRS Legislative Research","type":"Independent analysis","url":"https://prsindia.org/files/budget/budget_state/uttar-pradesh/2026/Budget_Analysis_2026-27-UP.pdf"},{"id":"S22","title":"UP Groundbreaking Ceremony 4.0","org":"Invest UP","type":"Government claim","url":"https://invest.up.gov.in/gbc/about_us.html"},{"id":"S23","title":"UP elections 2022 and 2017 party seats","org":"PRS Legislative Research","type":"Independent analysis","url":"https://prsindia.org/legislatures/state/vital-stats/profile-of-the-18th-uttar-pradesh-legislative-assembly"},{"id":"S24","title":"Government data: crimes against women 2023","org":"NCRB / Data.gov.in","type":"Primary administrative","url":"https://www.data.gov.in/catalog/crime-india-2023"},{"id":"S25","title":"State Water and Sanitation Mission rural tap-connection dashboard","org":"UP State Water and Sanitation Mission","type":"State administrative dashboard","url":"https://www.swsm.up.gov.in/"},{"id":"S26","title":"Jal Jeevan Mission: UP source dashboards and village reports","org":"Uttar Pradesh Jal Jeevan Mission","type":"State administrative dashboard","url":"https://jjm.up.gov.in/"},{"id":"S27","title":"Jal Jeevan Mission: reported and certified tap connections","org":"Ministry of Jal Shakti","type":"Central administrative dashboard","url":"https://ejalshakti.gov.in/jjmreport/JJMVillage.aspx"},{"id":"S28","title":"COVID-19 excess mortality and uncertainty","org":"Peer-reviewed public-health study","type":"Independent scientific research","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9128677/"},{"id":"S29","title":"UP Groundbreaking Ceremony / investor event background","org":"Invest UP","type":"Government claim","url":"https://invest.up.gov.in/gbc/about_us.html"},{"id":"S30","title":"Maha Kumbh 2025 stampede: initial confirmed and contested death counts","org":"Reuters / ThePrint","type":"Independent reporting","url":"https://theprint.in/india/dozens-killed-in-indias-kumbh-festival-stampede/2468925/"},{"id":"S32","title":"ASER 2024: Uttar Pradesh rural education report card (school enrolment and learning), pages 223–228","org":"ASER Centre / Pratham","type":"Independent household survey","url":"https://asercentre.org/wp-content/uploads/2022/12/Uttar-Pradesh-1.pdf"},{"id":"S33","title":"ASER 2024: Uttar Pradesh rural young-children report card, pages 1–4","org":"ASER Centre / Pratham","type":"Independent household survey","url":"https://asercentre.org/wp-content/uploads/2022/12/Uttar-Pradesh-2.pdf"},{"id":"S34","title":"CAG State Finances Audit Report 2023–24: 2025 report No. 06, tabled 12 August 2025","org":"Comptroller and Auditor General of India","type":"Constitutional financial audit","url":"https://www.cag.gov.in/en/audit-report/details/122472"},{"id":"S35","title":"PRS UP Budget 2026–27: Annexure 3, 2024–25 budget estimates versus audited actuals","org":"PRS Legislative Research / UP budget documents","type":"Independent budget analysis","url":"https://prsindia.org/budgets/states/uttar-pradesh-budget-analysis-2026-27"},{"id":"S36","title":"NFHS-5 versus NFHS-4, Uttar Pradesh comparative fact sheet: maternal and child care","org":"National Health Mission Uttar Pradesh / Ministry of Health and Family Welfare","type":"Primary household survey","url":"https://upnrhm.gov.in/NHM-Doc/NFHS/NFHS/NFHS-5%28FY%202019-21%29and-NFHS-4%28FY%202015-16%29Comparative%20Analysis.pdf"},{"id":"S37","title":"Uttar Pradesh NFHS-5 state report: district distribution of at least four antenatal visits","org":"National Health Mission Uttar Pradesh / IIPS","type":"Primary household survey","url":"https://upnrhm.gov.in/NHM-Doc/NFHS/NFHS/NFHS-5%28FY%202019-21%29Report.pdf"},{"id":"S38","title":"NFHS-5 child anaemia across states and NFHS-4 baseline","org":"PRS Legislative Research / Ministry of Health and Family Welfare","type":"Independent analysis of official survey","url":"https://prsindia.org/budgets/parliament/demand-for-grants-2023-24-analysis-women-and-child-development"},{"id":"S39","title":"Lok Sabha answer 3792 (16 March 2026): UP youth WPR and unemployment 2017–18 to 2023–24","org":"Ministry of Labour and Employment","type":"Primary parliamentary reply","url":"https://dge.gov.in/sites/default/files/2026-05/3792_eng.pdf"},{"id":"S40","title":"Lok Sabha answer 1118 (10 February 2025): UP labour-force outcomes for SC, ST and OBC groups","org":"Ministry of Labour and Employment","type":"Primary parliamentary reply","url":"https://dge.gov.in/dge/sites/default/files/2025-05/1118_e.pdf"},{"id":"S41","title":"PLFS Annual Report 2025: youth NEET rates and 2025 survey redesign","org":"Ministry of Statistics and Programme Implementation","type":"Primary household survey","url":"https://www.mospi.gov.in/uploads/publications_reports/publications_reports1780040415321_0624fb13-fb47-40bc-b470-7c7e9635c3ef_PLFS_2025_F_REV_29052026.pdf"},{"id":"S42","title":"Rajya Sabha reply 3734 (5 April 2023): state-wise registered murder cases and rates, 2017–21","org":"Ministry of Home Affairs","type":"Primary parliamentary reply","url":"https://xn--i1b5bzbybhfo5c8b4bxh.xn--11b7cb3a6a.xn--h2brj9c/MHA1/Par2017/pdfs/par2023-pdfs/RS05042023/3734.pdf"},{"id":"S43","title":"NCRB Crime in India 2022, Table 2A.1: registered murder cases, 2020–22 (published mirror)","org":"National Crime Records Bureau","type":"Official table, independent mirror","url":"https://images.assettype.com/barandbench/2023-12/dc0ba053-a1f0-4e6a-a5f8-e7668ddd2249/NCRB_STATS.pdf"},{"id":"S44","title":"NCRB Crime in India 2023 data catalogue: crimes against women, homicide and police statistics","org":"National Crime Records Bureau / Open Government Data","type":"Primary administrative statistics","url":"https://www.data.gov.in/catalog/crime-india-2023"},{"id":"S45","title":"Lok Sabha answer 5108 (24 March 2026): state-wise cybercrimes against women 2021–23","org":"Ministry of Home Affairs / archive transcript","type":"Archived parliamentary reply","url":"https://policyindex.ai/in/gazette/parliament-question-cyber-crime-against-women-fvdt8o"},{"id":"S46","title":"NCRB 2016: UP reported 49,262 offences against women, historical baseline","org":"The Indian Express / NCRB 2016","type":"Independent reporting of official statistics","url":"https://indianexpress.com/article/explained/ncrb-data-2016-cruelty-by-husband-sexual-assault-top-crimes-against-women-4962464/"},{"id":"S47","title":"CAG UP State Finances 2023–24, executive summary: unspent SNA funds and pending utilisation certificates","org":"Comptroller and Auditor General of India","type":"Primary constitutional financial audit","url":"https://cag.gov.in/uploads/download_audit_report/2025/06--Executive-Summary-2023-24-0689c82d0cf3583.02653094.pdf"},{"id":"S48","title":"Employment Indicators in India: youth unemployment by state, 2017–18 to 2023–24","org":"Directorate General of Employment / MoSPI","type":"Official statistical compilation","url":"https://dge.gov.in/dge/sites/default/files/2024-10/Employment_Indicators_In_India.pdf"},{"id":"S49","title":"NCRB 2023 registered offences against women: counts, population-adjusted rates and limitations","org":"The Times of India / NCRB","type":"Independent reporting of official statistics","url":"https://timesofindia.indiatimes.com/india/cruelty-by-husband-crimes-against-women-up-marginally-in-2023-ncrb-report/articleshow/124245044.cms"}],"topics":[{"id":"economy","nav":"Economy","group":"Economy & livelihoods","title":"Bigger economy. But what has changed for each resident?","deck":"Read the headline growth numbers alongside inflation, population, employment, and the difference between budget projections and actual output.","verdict":"Measured progress","sources":["S02","S16","S03","S13"],"grade":"B−","assessment":"Measured progress","outcome":"2024–25 real output growth was estimated at 9%, above the 6.5% national comparison. Yet per-capita output remained far below India’s figure.","analysis":"The aggregate economy has grown, but the distribution of gains is much less clear. At current prices, estimated per-capita GSDP was ₹1,24,366 in UP against ₹2,34,859 in all-India per-capita GDP in 2024–25. Those are related but not identical national-accounting measures.","caveat":"Output growth is a credible positive. The grade remains qualified because higher state GDP does not resolve weak per-person output, underemployment or unequal regional opportunity.","bottomLine":"Growth: strong estimate. Living standards: still behind. A governor’s record must be judged on both."},{"id":"budgets","nav":"Public finances","group":"Economy & livelihoods","title":"UP spends more on paper than it delivers. What the audited accounts reveal.","deck":"Budget estimates, collections and audited spending tell different stories. The gap repeats across years.","verdict":"Mixed outcomes","sources":["S47","S35","S34","S02","S13","S21"],"grade":"C","assessment":"Mixed outcomes","outcome":"FY2024–25 state own-tax receipts were ₹2,12,243 crore against a budget of ₹2,70,086 crore, 21% below forecast. Central grants were ₹50,330 crore against ₹93,465 crore budgeted, a 46% shortfall. Capital outlay was ₹1,14,001 crore versus ₹1,54,747 crore planned.","analysis":"The 2026–27 PRS budget analysis retrospectively compares FY2024–25 estimates with actuals. State GST brought in ₹82,872 crore versus ₹1,14,249 crore budgeted, 27% lower than forecast. Combined net expenditure was 18% below the initial FY2024–25 budget. Separately, the CAG audit for FY2023–24 identified 27 cases in 24 grants with persistent savings of at least ₹100 crore. Savings in those cases totalled ₹79,122.24 crore in FY2023–24. The CAG also recorded ₹3,312.20 crore in unnecessary supplementary provisions across 72 cases in 37 grants. The CAG's 2023–24 executive summary separately noted ₹19,478.31 crore lying unspent in Single Nodal Agency bank accounts on 31 March 2024, and 17,963 outstanding utilisation certificates for ₹11,872.95 crore spanning releases from 2001–02 to September 2022. These are different stock and flow measures, and must not be added to one another or attributed entirely to the present government.","caveat":"A budget shortfall is not automatically a year-on-year economic contraction. Lower actual tax collections may reflect forecasting error, lower-than-expected activity or timing and accounting factors. Central grant receipts depend on Union-state transfer and scheme conditions. The CAG's ₹79,122.24 crore relates to a particular group of grants in FY2023–24, not to the entire FY2024–25 budget and must not be added to PRS's ₹40,746 crore capital-outlay gap. The government reported a 2.1% fiscal deficit in FY2024–25; a lower deficit alone does not prove successful spending delivery. The outstanding utilisation certificates include grants from well before 2017, while the SNA bank balance is a snapshot of funds outside the state Treasury; neither amount should be represented as annual lost expenditure.","bottomLine":"The state pursued ambitious fiscal and capital plans, but audited actuals show material and repeated forecasting and execution gaps. Judge the record by results delivered against allocations."},{"id":"poverty","nav":"Poverty & welfare","group":"People & services","title":"More households have escaped multiple deprivations. Which gaps remain?","deck":"Multidimensional poverty is not the same as an income-poverty rate.","verdict":"Clear improvement","sources":["S06","S07","S19"],"grade":"B+","assessment":"Clear improvement","outcome":"The share of people facing multidimensional poverty fell from 37.68% (2015–16) to 22.93% (2019–21): a decline of 14.75 percentage points.","analysis":"This is one of the strongest positive changes supported by comparable household-survey data. Improvements span overlapping national and state programmes across housing, sanitation, fuel, education and health.","caveat":"The observation covers a period before and after March 2017, so it cannot be wholly assigned to one administration. Moreover, roughly 23% still met the deprivation threshold in the later survey.","bottomLine":"A substantial fall in deprivation, with a very large unfinished task."},{"id":"health","nav":"Health & nutrition","group":"People & services","title":"Child stunting fell. Severe wasting rose.","deck":"Health outcomes produce a more complicated picture than hospital openings and programme announcements.","verdict":"Mixed outcomes","sources":["S36","S38","S08","S21","S01"],"grade":"C","assessment":"Mixed outcomes","outcome":"Child stunting fell from 46.3% to 39.7% and underweight from 39.5% to 32.1%, but severe wasting rose from 6.0% to 7.3%. Anaemia among children aged 6–59 months rose from 63.2% to 66.4% (NFHS-4 versus NFHS-5).","analysis":"The NFHS series reports a reduction in chronic undernutrition, with stunting down 6.6 percentage points and underweight down 7.4 points. Maternal and preventive care also expanded: institutional births rose from 67.8% to 83.4%, and full basic vaccination of children aged 12–23 months from 51.1% to 69.6%. These gains are meaningful. Nevertheless, improvement in service contact does not imply improvement in every nutritional outcome.","caveat":"Severe wasting and child anaemia both worsened in the same survey comparison. In 2019–21, two in three children aged 6–59 months were classified as anaemic. Survey timing spans pre-lockdown and post-lockdown interviews and includes effects of longstanding Union and state programmes. Haemoglobin-based anaemia measures have their own technical and comparability limitations.","bottomLine":"UP improved maternal contact, vaccination and several child-growth indicators, but stubbornly high malnutrition and worsening childhood anaemia prevent an unqualified positive health rating."},{"id":"education","nav":"Schools & learning","group":"People & services","title":"Government-school reading improved. Most children still miss the grade-level benchmark.","deck":"ASER follows children's reading and arithmetic skills in their own homes, not school publicity or examination pass rates.","verdict":"Evidence incomplete","sources":["S32","S33","S09","S21"],"grade":"B−","assessment":"Substantial measured improvement / still weak proficiency","outcome":"In rural UP government schools, the share of Class III children reading a Class II-level text increased from 12.3% in 2018 to 27.9% in 2024. Class V rose from 36.2% to 50.5%; Class VIII from 62.0% to 67.3%.","analysis":"The ASER state report provides a longer series for government-school Class III reading: 6.0% (2014), 7.2% (2016), 12.3% (2018), 16.4% (2022) and 27.9% (2024). The improvement is both a recovery and a continuation of a pre-pandemic upward trend. In Class II, government-school recognition of at least words climbed from 21.7% (2018) to 44.4% (2024), while recognition of numbers up to 99 increased from 22.5% to 41.8%. The evidence is based on independently administered household assessments.","caveat":"Reading at Class II level remains out of reach for 72.1% of government-school Class III pupils assessed in 2024. Among Class III pupils at private schools, 43.0% met that benchmark in 2024, a 15.1-point gap. In Class II, 67.4% of private-school children could recognise words, versus 44.4% of government-school children. ASER covers rural sampled districts (70 of 71 under its Census 2011 sampling frame), not every urban child or every administrative district. Improvements cannot be attributed solely to one scheme.","bottomLine":"UP has achieved substantial, independently measured improvement in foundational learning. It is an important positive governance outcome, but basic proficiency and school-type gaps remain large."},{"id":"law","nav":"Crime & policing","group":"Justice, rights & institutions","title":"Has the rule of law improved? Separate crime, enforcement and justice.","deck":"Recorded FIRs, crime rates, convictions and encounters do not measure the same thing.","verdict":"Contested, not scored","sources":["S42","S43","S11","S10","S18"],"grade":null,"assessment":"Contested, not scored","outcome":"Registered murders declined from 4,324 in 2017 to 3,491 in 2022. At the same time, law-enforcement methods and the rights of suspects cannot be judged from the homicide count alone.","analysis":"A parliamentary answer and NCRB's 2022 murder table support a downward series of registered homicide. It is an important improvement in a serious-offence indicator. However, murder-rate change, FIR registration, police encounters, crowd violence, prosecution outcomes and compliance with court safeguards measure different dimensions. Assessing them under one crime headline would overstate what is known.","caveat":"The period includes part of 2017 under the previous state government and the abnormal pandemic year 2020. The Supreme Court issued nationwide safeguards against punitive demolitions in November 2024. The ruling establishes due-process requirements but does not by itself provide an incident-level UP count of unlawful demolitions. Broader convictions, custodial deaths, due-process compliance and independently corroborated victimisation remain insufficient for an overall rule-of-law rating.","bottomLine":"Recorded homicide improved. A statewide police-and-justice score remains unwarranted without evidence on other offences and constitutional safeguards."},{"id":"women","nav":"Women & children","group":"People & services","title":"More offences against women were registered. What does that tell us about safety?","deck":"Counts, crime rates, reporting access and actual victimisation do not move identically.","verdict":"Evidence incomplete","sources":["S44","S45","S46","S49","S10","S08"],"grade":null,"assessment":"Evidence incomplete","outcome":"Uttar Pradesh registered 49,262 offences against women in 2016, 56,083 in 2021, 65,743 in 2022 and 66,381 in 2023. Its 2023 population-adjusted recorded crime rate was 58.6 per 100,000 women, below the national 66.2.","analysis":"The historical baseline comes from NCRB 2016 reporting and the later figures from the NCRB Crime in India 2023 release. Absolute UP counts are among the largest nationally, consistent with the state's size. The rate uses an estimate of the female population rather than raw cases, and thus answers a different question. The rate in 2023 was below the national average. A separate MHA parliamentary annexure lists cybercrimes against women rising from 958 registered cases in UP in 2021 to 1,101 in 2022 and 1,463 in 2023, a 52.7% recorded increase over two years.","caveat":"An increase in registered cases can mean higher incidence, improved reporting, improved access or combinations thereof. A low registered rate does not necessarily indicate that women are safer if victims face barriers to reporting. Conversely, the largest raw count does not prove the highest individual risk. Broad definitions of crime against women combine many offence types. To establish a stronger result, compare specific offence rates, repeat victimisation, conviction and attrition, helpline responsiveness and household survey reports.","bottomLine":"The official record simultaneously shows high absolute registered counts, a below-national-average rate in 2023 and rising recorded cyber-offences. Those findings do not support a simplistic claim that UP is either the safest or the most dangerous state for women."},{"id":"roads","nav":"Roads & transport","group":"Infrastructure & environment","title":"Expressways changed connectivity. Who is connected to the gains?","deck":"Expressway construction is visible. Travel, safety and economic outcomes need separate evidence.","verdict":"Visible assets, outcomes uncertain","sources":["S02","S21","S03","S13"],"grade":null,"assessment":"Visible assets, outcomes uncertain","outcome":"The government has pursued major expressway and roads spending. The cited budget allocates a higher share to roads and bridges than the selected all-state benchmark.","analysis":"PRS records roads and bridges at 5.6% of UP’s FY2026–27 sectoral spending, against 4.3% in the FY2025–26 state-average comparison. Major projects are tangible, but the comparison is spending intent rather than direct measurement of connectivity.","caveat":"Neither kilometres announced nor ceremonies establish reductions in freight cost, journey time, road casualties or regional income. Infrastructure attribution also requires checking project origins.","bottomLine":"Construction is visible. Its net public benefit requires a different evidence standard."},{"id":"industry","nav":"Jobs & investment","group":"Economy & livelihoods","title":"An MoU is not a factory, and projected jobs are not payrolls.","deck":"Investment reporting needs four distinct stages: intent, grounding, commissioning and sustained operation.","verdict":"Announcements exceed verified outcomes","sources":["S14","S15","S22","S16"],"grade":null,"assessment":"Announcements exceed verified outcomes","outcome":"The scale of investment pledges has been extraordinary. The conversion into sustained production and payroll jobs is much harder to prove.","analysis":"Invest UP reported investment proposals above ₹35 lakh crore around the 2023 summit. MoUs are expressions of interest, while groundbreaking, commissioning and employment represent later, separate stages.","caveat":"No firm-level audited investment conversion or durable employment total is established in the cited sources. An impressive announcement is not a recorded outcome.","bottomLine":"Investment intent is large. Verified operating value is a separate question."},{"id":"agriculture","nav":"Farming & rural UP","group":"Economy & livelihoods","title":"Farm income, water and procurement are the rural balance sheet.","deck":"The rural balance sheet includes farm prices, costs, irrigation and household income.","verdict":"Evidence incomplete","sources":["S02","S21","S13"],"grade":null,"assessment":"Evidence incomplete","outcome":"Agriculture remains central to UP’s economy, contributing an estimated 27% of GSDP in 2024–25.","analysis":"Crop production, procurement, MSP purchases, sugarcane payments and irrigation change farm finances differently across western UP, the Terai, eastern UP and Bundelkhand.","caveat":"A headline output figure cannot establish growth in inflation-adjusted net farmer income. The evidence shown does not support a single state-level agricultural grade.","bottomLine":"Agricultural contribution is established; farmer prosperity is not inferred from it."},{"id":"environment","nav":"Air, water & ecology","group":"Infrastructure & environment","title":"Air pollution and water stress do not stop at city limits.","deck":"Track actual quality and ecological damage, not only sanctioned plans.","verdict":"Material risks, limited trend data","sources":["S05","S20","S13"],"grade":null,"assessment":"Material risks, limited trend data","outcome":"UP’s district-specific SDG publication shows a climate-action score of 43.22 and a Goal 7 score of 100 in 2023–24.","analysis":"Those are distinct dimensions in a state-specific composite framework, not directly comparable environmental metrics. Power access and climate resilience do not move in lockstep.","caveat":"A trend grade requires consistent year-on-year PM2.5, groundwater, sewage, flood-risk and ecological indicators. The published values here do not constitute that series.","bottomLine":"Environmental outcomes need pollution exposure and resilience data, not a single index snapshot."},{"id":"politics","nav":"Elections & governance","group":"Justice, rights & institutions","title":"Two mandates, a changing electoral coalition.","deck":"BJP stayed in government in 2022, but the constituency and seat arithmetic changed.","verdict":"Democratic mandate, not outcome rated","sources":["S12","S23"],"grade":null,"assessment":"Democratic mandate, not outcome rated","outcome":"The BJP won 312 seats in 2017 and 255 in 2022; the Samajwadi Party moved from 47 to 111.","analysis":"The incumbent returned to office with a majority while surrendering 57 party seats. Elections measure electoral choices in particular contests, not direct causal evaluations of each public service.","caveat":"An editorial score for electoral outcomes would confuse voter choice with performance evidence. The political arc is reported factually without a policy grade.","bottomLine":"Two mandates coexist with an appreciable change in the seat distribution."},{"id":"districts","nav":"District inequality","group":"Geography","title":"The state average is not a district.","deck":"A statewide average conceals a wide spread in district development indicators.","verdict":"Uneven across 75 districts","sources":["S05","S06","S20"],"grade":null,"assessment":"Uneven across 75 districts","outcome":"UP’s own 2023–24 district SDG Index spans 57.74 to 74.19, grouping 42 districts as front-runners and 33 as performers.","analysis":"This spread shows why state averages conceal uneven outcomes. The state index aggregate of 68.72 is a different series from NITI’s national state index score of 67, and their components should not be interchanged.","caveat":"These composite scores are cross-sectional. They do not prove a district improved because of decisions made after 2017.","bottomLine":"The range is real. It is not a time-series performance rating."},{"id":"electricity","nav":"Electricity & energy","group":"Infrastructure & environment","title":"More homes have electricity. Is the supply affordable and dependable?","deck":"Measure connections, hours delivered, quality of service, subsidy cost and distribution-company finances separately.","verdict":"Clear access improvement","sources":["S08","S21","S13"],"grade":"B+","assessment":"Clear access improvement","outcome":"The share of UP’s population in households with electricity rose from 72.6% in NFHS-4 to 91.0% in NFHS-5.","analysis":"The comparable household-survey measure shows a large access gain over the 2015–16 to 2020–21 interval. The result is consistent with wider electrification efforts involving state delivery and national schemes.","caveat":"A connection does not prove uninterrupted power, affordable tariffs or healthy distribution-company finances. The time period also overlaps policies before and after 2017.","bottomLine":"An impressive access outcome, without a complete reliability verdict."},{"id":"water","nav":"Water & sanitation","group":"People & services","title":"From tap connections to water that arrives every day.","deck":"Reported coverage, certified functionality, water quality and household experience must never be conflated.","verdict":"Reported expansion, qualified","sources":["S25","S27","S08","S26"],"grade":"B−","assessment":"Reported expansion, qualified","outcome":"UP’s rural-water dashboard displays tap-connection coverage of 1.932% in August 2019 and 91.75% in a later dashboard panel.","analysis":"The scale of administratively recorded coverage is substantial. The source is an official programme dashboard, rather than a representative survey of consistent daily supply.","caveat":"The page also displays a separate 81.81% figure for households receiving tap water supply. These figures use different dashboard panels and must not be treated as independently reconciled measures of reliable safe supply.","bottomLine":"Large reported rollout; actual daily delivery and water quality remain decisive."},{"id":"urban","nav":"Cities & housing","group":"People & services","title":"Construction grows faster than the evidence on liveability.","deck":"Look past project announcements to the conditions that shape everyday city life.","verdict":"Outcome evidence incomplete","sources":["S02","S13","S08"],"grade":null,"assessment":"Outcome evidence incomplete","outcome":"Urban development announcements are easier to count than reliable drainage, affordable housing or cleaner air.","analysis":"Developing authorities and large construction schemes can transform neighbourhoods while generating displacement and maintenance costs. The impacts differ sharply between NCR cities, Lucknow, Kanpur, Varanasi and smaller towns.","caveat":"No consistent city-level panel of housing affordability, flood events, air quality and municipal service reliability underpins a statewide grade.","bottomLine":"A modern skyline is not a sufficient measure of liveability."},{"id":"tourism","nav":"Tourism & faith","group":"Infrastructure & environment","title":"Faith, tourism and the economics of the street.","deck":"From pilgrimage growth to crowd safety, what would count as genuine gains for residents?","verdict":"Benefits and safety both matter","sources":["S30","S13"],"grade":null,"assessment":"Benefits and safety both matter","outcome":"Religious tourism has become a major element of UP’s development narrative, but visitor counts are not local income.","analysis":"The 29 January 2025 Maha Kumbh crowd crush demonstrates why crowd safety is a central test alongside visitor arrivals. Contemporaneous official death totals and media reports should be identified by date rather than silently merged.","caveat":"Without consistent expenditure, employment and visitor-level data, it would be misleading to assign a statewide tourism outcome grade.","bottomLine":"A complete account weighs economic activity, resident rights and safety together."},{"id":"covid","nav":"COVID & emergency response","group":"People & services","title":"The hardest test of administration came during the pandemic.","deck":"A serious evaluation must reconcile hospital capacity, mortality, migration, education loss and the limits of the registration system.","verdict":"High uncertainty","sources":["S28","S08"],"grade":null,"assessment":"High uncertainty","outcome":"Official recorded COVID deaths and estimates of all-cause excess mortality answer different questions.","analysis":"Uncertain registration completeness, model assumptions and health-system data gaps complicate any simple state-vs-state mortality comparison. Pandemic disruption also changed employment, migration and schooling.","caveat":"One cited excess-mortality study acknowledged limited UP data after April 2021. It should not be presented as an uncontested UP-specific death total.","bottomLine":"Pandemic accountability is important, but incomplete evidence must remain visible."},{"id":"equity","nav":"Social inclusion","group":"Justice, rights & institutions","title":"Development must be examined across caste, gender, disability and religion.","deck":"Statewide growth and welfare totals can mask differential treatment or uneven access to justice.","verdict":"Not independently rated","sources":["S40","S39","S06","S08","S10","S11"],"grade":null,"assessment":"Not independently rated","outcome":"UP's usual-status worker-population ratio increased across Scheduled Castes, Scheduled Tribes and Other Backward Classes between 2017–18 and 2023–24, according to a February 2025 Lok Sabha reply.","analysis":"The Union labour ministry reported worker-population ratios increasing from 35.2% to 43.6% for Scheduled Castes, from 40.0% to 52.0% for Scheduled Tribes, and from 34.1% to 43.0% for Other Backward Classes. Corresponding unemployment rates also declined. These are legitimate favourable outcomes for labour participation among the groups, but they do not establish wage equality, opportunity in public appointments or discrimination trends.","caveat":"PLFS usual-status employment includes principal and subsidiary work, not only regular or salaried work. Different group sample sizes imply different statistical precision, particularly where a subgroup represents a small share of the state population. There are no valid numbers for an EWS trend in the cited parliamentary table. A comprehensive social-inclusion score must incorporate health, education, police response, income and legal access in addition to workforce participation.","bottomLine":"Employment participation improved across the three reported groups. There is still inadequate evidence for a defensible overall equity rating."},{"id":"early-years","nav":"Early childhood","group":"People & services","title":"Half of rural UP’s three-year-olds are outside preschool.","deck":"Children's first encounters with preschool remain a major inequality even as enrolment improves.","grade":"C","assessment":"Improving enrolment / persistent access gap","outcome":"Among rural Uttar Pradesh children aged three, the proportion enrolled in neither preschool nor school fell from 64.7% in 2018 to 52.1% in 2024. For four-year-olds it fell from 42.3% to 30.0%.","analysis":"ASER's 2024 young-children report card establishes a comparable three-wave picture: among children aged three, non-enrolment was 64.7% in 2018, 51.9% in 2022 and 52.1% in 2024. At age four the shares were 42.3%, 33.0% and 30.0%; at age five, 18.0%, 11.9% and 14.9%. This shows a long-run improvement, but not uniform progress after 2022. The same report records an increase in anganwadi attendance at age five from 23.6% (2022) to 28.3% (2024).","caveat":"The 2024 all-India rural rate of three-year-olds out of preschool or school was 20.7%, far below UP's 52.1%; this is a substantial remaining disparity. This is a household sample based on the 2011 district frame, covering 70 of 71 historical districts, not an administrative count of all 75 current districts. Non-enrolment cannot by itself measure childcare quality, cognitive development or parental preference.","bottomLine":"UP made a sizeable improvement since 2018, but more than half of rural three-year-olds were still outside organised preschool in 2024 and the national gap was wide.","sources":["S33","S32","S09"]},{"id":"maternal","nav":"Maternal & child care","group":"People & services","title":"More mothers reach care. The next challenge is quality and equity.","deck":"More hospital births, antenatal visits and child vaccinations are measurable gains, with large uncovered populations and district disparities.","grade":"B−","assessment":"Significant coverage gains / large remaining gaps","outcome":"NFHS records institutional births rising from 67.8% (2015–16) to 83.4% (2019–21), at least four antenatal visits from 26.4% to 42.4%, and full basic vaccination of children aged 12–23 months from 51.1% to 69.6%.","analysis":"The gains are broad: first-trimester antenatal check-ups rose from 45.9% to 62.5%, and the share of recent mothers receiving postnatal care within two days of delivery rose from 54.0% to 72.0%. Public-facility births increased from 44.5% to 57.7%. These figures come from the same NFHS household survey series, allowing stronger historical comparison than lists of hospital inaugurations.","caveat":"In the later survey, fewer than half of recent mothers (42.4%) reported at least four antenatal visits, and 30.4% of children aged 12–23 months still lacked the survey's full basic vaccination schedule. District coverage varied sharply: Kanpur Nagar 70% and Ghaziabad 62% for four or more antenatal visits, versus Barabanki 23% and Unnao 20%. The five-year birth recall windows overlap different policy periods. These data indicate contacts with health services, not independent verification of diagnosis, clinical quality or mortality.","bottomLine":"An appreciable expansion in maternity and immunisation services is a positive outcome; serious access and district gaps mean it is not an unqualified success.","sources":["S36","S37","S08"]},{"id":"youth-employment","nav":"Youth employment","group":"Economy & livelihoods","title":"More young people are working. Are these good jobs?","deck":"Youth unemployment has fallen, and the employment-to-population ratio has increased. Neither measure independently proves higher earnings or employment security.","grade":"B−","assessment":"Measured employment gains / quality still unproven","outcome":"For UP residents aged 15–29, the official PLFS usual-status unemployment rate fell from 16.7% in 2017–18 to 9.1% in 2023–24, while the worker-population ratio increased from 28.1% to 39.0%.","analysis":"A March 2026 Lok Sabha reply provides a like-for-like 2017–18 to 2023–24 state comparison, from two PLFS annual samples. UP's youth worker-population ratio improved by 10.9 percentage points, although it remained below the all-India 2023–24 youth ratio of 41.7%. The youth unemployment rate declined by 7.6 points. India as a whole also recorded falling youth unemployment over this period, from 17.8% to 10.2%. These comparisons are more meaningful than counts of MoUs or estimated jobs from foundation ceremonies.","caveat":"The usual-status definition includes principal and subsidiary economic activity, including some unpaid family work and marginal labour. A person classified as employed can still be underemployed, underpaid or without an employment contract. The available comparison does not quantify UP's real monthly earnings, salaried-work share, social insurance or migration. PLFS changed sample design and adopted calendar-year reporting in 2025, so 2025 should not be appended mechanically to the 2017–24 series. In the separately redesigned 2025 survey, 29.1% of UP people aged 15–29 were neither in employment, education nor training (NEET), compared with 25.0% nationally.","bottomLine":"A substantial, survey-backed improvement in youth employment is credible. A full jobs-success verdict also needs independent earnings, regular-work and underemployment evidence.","sources":["S39","S48","S41","S16"]},{"id":"homicide","nav":"Homicide trends","group":"Justice, rights & institutions","title":"Reported murders fell. That does not settle the rule-of-law debate.","deck":"One serious-offence series points to declining registered homicide, while broader safety and procedural justice require separate evaluation.","grade":"B−","assessment":"Improved measured outcome / attribution limited","outcome":"NCRB data record 4,324 murder cases in Uttar Pradesh in 2017, 3,717 in 2021 and 3,491 in 2022. The rate fell from 1.9 per 100,000 population in 2017 to 1.5 in 2022.","analysis":"The Ministry of Home Affairs' 2023 Rajya Sabha reply gives a complete 2017–21 series: 4,324, 4,018, 3,806, 3,779 and 3,717 reported murder cases. NCRB's Crime in India 2022 table adds 3,491 in 2022. The fall from 2017 to 2022 is 833 registered cases, about 19.3%. Because UP's population also grew, its recorded murder rate declined more than the raw case count alone suggests. The pattern is meaningful and deserves recognition in any public-safety assessment.","caveat":"2017 includes months before the March change of government, and crime-reporting patterns, investigation practices and definitions affect administrative records. The 2020 pandemic changed ordinary mobility. The homicide series does not establish that police encounters were lawful or caused the reduction, nor does it determine trends in rape, kidnapping, cybercrime, extortion, mob violence, extrajudicial punishment or judicial backlog. The letter grade applies to the registered-homicide outcome only, not to the UP police or all of law and order.","bottomLine":"The decline in recorded murders is a substantiated positive trend. It is not a substitute for independent legal scrutiny of enforcement or the outcomes of other crime categories.","sources":["S42","S43","S10","S11"]}],"timeline":[{"date":"2017-03","title":"Yogi Adityanath takes office","type":"Government","body":"Yogi Adityanath was sworn in on 19 March 2017 after the BJP won 312 of 403 Assembly seats.","refs":["S12"]},{"date":"2018","title":"First SDG India Index baseline","type":"Data","body":"UP scores 42 on NITI Aayog’s national SDG index.","refs":["S04"]},{"date":"2019-20","title":"Second SDG index","type":"Data","body":"UP’s national index score rises to 55.","refs":["S04"]},{"date":"2020","title":"Pandemic begins; statewide disruption","type":"Public health","body":"Treat 2020 health, migration, school and crime-registration data as a structural break.","refs":["S08","S10"]},{"date":"2020-21","title":"NFHS-5 fieldwork concludes","type":"Survey","body":"The state-level survey reveals improved sanitation and electricity access alongside persistent malnutrition.","refs":["S08"]},{"date":"2020-21","title":"Third SDG index","type":"Data","body":"UP reaches 60 on the NITI national SDG index.","refs":["S04"]},{"date":"2021-04","title":"COVID second-wave emergency","type":"Public health","body":"The second COVID wave places hospital preparedness, clinical care and the completeness of mortality data under scrutiny.","refs":["S28"]},{"date":"2022-03","title":"Second Assembly mandate","type":"Election","body":"BJP wins 255 seats, down from 312; SP wins 111, up from 47.","refs":["S12"]},{"date":"2023-02","title":"Global Investors Summit","type":"Investment","body":"Investment summit MoUs represent proposed investments, not completed production or verified payroll jobs.","refs":["S14"]},{"date":"2023-07","title":"NITI / UNDP MPI assessment","type":"Poverty","body":"2015-16 to 2019-21 UP multidimensional poverty falls by 14.75 percentage points.","refs":["S06"]},{"date":"2023-12","title":"NCRB 2022 confirms lower registered murders","type":"Crime","body":"UP records 3,491 murder cases in 2022, compared with 4,324 in 2017. The outcome is not proof that all policing or prosecution improved.","refs":["S43","S42"]},{"date":"2024-02","title":"Groundbreaking Ceremony 4.0","type":"Investment","body":"Government describes projects progressing through implementation, distinct from fully commissioned plants.","refs":["S22"]},{"date":"2024-07","title":"SDG India Index 2023-24","type":"Data","body":"UP reaches 67 on the national index, an increase of 25 points since 2018.","refs":["S04"]},{"date":"2024-11","title":"Supreme Court demolition judgment","type":"Judiciary","body":"A nationwide rule-of-law ruling establishes procedural safeguards against punitive demolition.","refs":["S11"]},{"date":"2025-01","title":"Maha Kumbh crowd crush","type":"Public safety","body":"A major loss of life in Prayagraj raises verifiable questions about crowd control, rescue and the accuracy of casualty totals.","refs":["S30"]},{"date":"2025-01","title":"ASER 2024 released: early learning and preschool gaps","type":"Education","body":"Independent household assessments report major gains in reading, while more than half of rural three-year-olds remain outside preschool and school.","refs":["S32","S33"]},{"date":"2025-02","title":"Lok Sabha publishes UP employment trends by social group","type":"Employment","body":"The labour ministry reports rising usual-status worker-population ratios among SC, ST and OBC groups for 2017–18 to 2023–24.","refs":["S40"]},{"date":"2025-08","title":"CAG state finance audit tabled","type":"Audit","body":"Audit of UP’s financial year 2023-24 becomes available in the legislature.","refs":["S13"]},{"date":"2025-08","title":"CAG 2023–24 state-finances audit presented","type":"Audit","body":"The audit records persistent savings across 27 grant cases, totalling ₹79,122.24 crore in that subset for FY2023–24.","refs":["S34"]},{"date":"2025-09","title":"NCRB Crime in India 2023 published","type":"Crime","body":"The official report records 66,381 offences against women in UP in 2023, requiring comparison with population and reporting practices.","refs":["S44","S49"]},{"date":"2026-02","title":"State budget 2026-27","type":"Budget","body":"Uttar Pradesh proposes ₹9,12,696 crore in total 2026–27 expenditure including debt repayments. The budget is an estimate, not actual spending.","refs":["S01","S02"]},{"date":"2026-03","title":"Parliament answers UP's youth unemployment and job question","type":"Employment","body":"The labour ministry puts UP youth unemployment at 9.1% in 2023–24 against 16.7% in 2017–18, with worker-population ratio increasing from 28.1% to 39.0%.","refs":["S39"]},{"date":"2026-05","title":"PLFS 2025 releases revised-format workforce and NEET data","type":"Data","body":"The new survey shows 29.1% of UP people aged 15–29 outside employment, education and training, above the all-India 25.0%. Methodology changed, precluding naive continuation.","refs":["S41"]}],"metrics":[{"label":"NITI national SDG score","n":"67 / 100","sub":"2023–24; up from 42 in 2018","tone":"positive","source":"S04"},{"label":"UP multidimensional poverty","n":"22.93%","sub":"2019–21; 37.68% in 2015–16","tone":"positive","source":"S06"},{"label":"Children under 5 stunted","n":"39.7%","sub":"2020–21; 46.3% in 2015–16","tone":"mixed","source":"S08"},{"label":"Per-capita GSDP","n":"₹1.24 lakh","sub":"2024–25 estimate; current prices","tone":"neutral","source":"S02"},{"label":"Capital outlay underspend","n":"~28%","sub":"Mean annual gap, FY2021–22 to FY2024–25","tone":"caution","source":"S02"},{"label":"Improved sanitation","n":"68.8%","sub":"2020–21; up from 36.4% in 2015–16","tone":"positive","source":"S08"},{"label":"Class III govt-school reading","n":"27.9%","sub":"Rural UP, 2024; 12.3% in 2018","tone":"positive","source":"S32"},{"label":"Rural three-year-olds not in preschool","n":"52.1%","sub":"ASER 2024; 64.7% in 2018","tone":"caution","source":"S33"},{"label":"Institutional births","n":"83.4%","sub":"NFHS-5; up from 67.8% in NFHS-4","tone":"positive","source":"S36"},{"label":"Childhood anaemia","n":"66.4%","sub":"6–59 months; 63.2% in NFHS-4","tone":"caution","source":"S36"},{"label":"Youth unemployment rate","n":"9.1%","sub":"2023–24; down from 16.7% in 2017–18","tone":"positive","source":"S39"},{"label":"Youth worker-population ratio","n":"39.0%","sub":"2023–24; up from 28.1% in 2017–18","tone":"positive","source":"S39"},{"label":"Registered murders","n":"3,491","sub":"NCRB 2022; 4,324 in 2017","tone":"positive","source":"S43"},{"label":"Women-related FIRs","n":"66,381","sub":"NCRB 2023; recorded rate 58.6 per 100k women","tone":"mixed","source":"S44"},{"label":"Unspent SNA balances","n":"₹19,478 cr","sub":"CAG, 31 March 2024, bank-balance snapshot","tone":"caution","source":"S47"}],"comparisons":[{"id":"households","title":"Basic household facilities","unit":"% of population in households","note":"NFHS-4 (2015–16) versus NFHS-5 (2020–21), same state survey series. A toilet is not evidence of safe wastewater treatment.","source":"S08","items":[{"name":"Electricity access","before":72.6,"after":91},{"name":"Improved sanitation","before":36.4,"after":68.8},{"name":"Clean cooking fuel","before":32.7,"after":49.5}]},{"id":"nutrition","title":"Child nutrition outcomes","unit":"% of children under five","note":"Lower is better for stunting, underweight, severe wasting and anaemia. NFHS-4 2015–16 versus NFHS-5 2019–21, Uttar Pradesh. Child anaemia increased despite reductions in stunting and underweight.","source":"S36","items":[{"name":"Stunted","before":46.3,"after":39.7},{"name":"Underweight","before":39.5,"after":32.1},{"name":"Severely wasted","before":6,"after":7.3},{"name":"Anaemia, age 6–59 months","before":63.2,"after":66.4}]},{"id":"sdg","title":"National SDG Index trajectory","unit":"NITI Aayog national composite score","note":"Index score is not an annual outcome series. Survey methodologies and indicator sets must be reviewed when comparing editions.","source":"S04","items":[{"name":"2018","score":42},{"name":"2019–20","score":55},{"name":"2020–21","score":60},{"name":"2023–24","score":67}]},{"id":"spending","title":"2026–27 spending priorities vs state benchmark","unit":"% of sectoral expenditure","note":"UP 2026–27 budget estimate vs the cross-state 2025–26 budget average published by PRS. Different fiscal years. Not outcomes.","source":"S21","items":[{"name":"Education","before":14.5,"after":12.8},{"name":"Health","before":6.2,"after":6.3},{"name":"Roads & bridges","before":4.3,"after":5.6},{"name":"Agriculture","before":5.7,"after":3.7}]},{"id":"capital","title":"Capital outlay: announced vs actual","unit":"₹ crore","note":"UP budget estimate and actual annual capital outlay as compiled by PRS. Reporting periods are financial years, not calendar years.","source":"S02","items":[{"name":"2021–22","before":113768,"after":71443},{"name":"2022–23","before":123920,"after":93028},{"name":"2023–24","before":147492,"after":110555},{"name":"2024–25","before":154747,"after":114001}]},{"id":"water","title":"Reported rural tap-connection coverage","unit":"% of rural households, administrative dashboard","note":"UP State Water and Sanitation Mission: 15 Aug 2019 vs dashboard accessed October 2026. This measures recorded tap connections, not proof of regular potable water. Household denominators can change.","source":"S25","items":[{"name":"Rural household taps","before":1.932,"after":91.75}]},{"id":"school","title":"Rural government-school reading proficiency","unit":"% of enrolled pupils who can read Class II-level text","note":"ASER 2018 versus 2024; Class III, V and VIII pupils enrolled in government schools. Class III private-school pupils shown as a comparator. Survey covers rural sampled districts; higher values mean better learning outcomes.","source":"S32","items":[{"name":"Class III · government","before":12.3,"after":27.9},{"name":"Class V · government","before":36.2,"after":50.5},{"name":"Class VIII · government","before":62,"after":67.3},{"name":"Class III · private","before":45.4,"after":43}]},{"id":"preschool","title":"Young children outside preschool or school","unit":"% of rural children not enrolled in preschool or school","note":"ASER rural UP, 2018 versus 2024. Lower values mean higher enrolment. At age three the all-India 2024 figure is 20.7%. The indicator does not establish service quality.","source":"S33","items":[{"name":"Age three","before":64.7,"after":52.1},{"name":"Age four","before":42.3,"after":30},{"name":"Age five","before":18,"after":14.9}]},{"id":"revenue","title":"FY2024–25 receipts: budget versus actual","unit":"₹ crore, state budget estimates (BE) and actuals","note":"2024–25 state budget versus actuals, as compiled by PRS. SGST is included within total own-tax revenue, not an additional independent category. Variances are against budget forecasts, not year-on-year changes.","source":"S35","items":[{"name":"Own-tax receipts","before":270086,"after":212243},{"name":"Of which: State GST","before":114249,"after":82872},{"name":"Union grants received","before":93465,"after":50330}]},{"id":"school-trend","title":"Class III reading: a decade of change","unit":"% of rural UP government-school Class III pupils reading Class II text","note":"ASER sample survey of households: 2014, 2016, 2018, 2022 and 2024. Values describe tested reading outcomes, not pass rates or entire school-system quality.","source":"S32","items":[{"name":"2014","score":6},{"name":"2016","score":7.2},{"name":"2018","score":12.3},{"name":"2022","score":16.4},{"name":"2024","score":27.9}]},{"id":"maternal","title":"Maternal services and basic vaccination","unit":"% coverage in Uttar Pradesh households (NFHS-4 to NFHS-5)","note":"2015–16 versus 2019–21. These are survey measures of contact and coverage, not independently observed clinical quality. Birth indicators use stated recall periods; higher means better coverage.","source":"S36","items":[{"name":"Institutional births","before":67.8,"after":83.4},{"name":"At least four antenatal visits","before":26.4,"after":42.4},{"name":"Full basic vaccination","before":51.1,"after":69.6},{"name":"Public-facility births","before":44.5,"after":57.7}]},{"id":"district-anc","title":"District inequality in antenatal care","unit":"% mothers with at least four antenatal care visits, NFHS-5","note":"Selected districts, not a comprehensive district ranking. NFHS-5 Uttar Pradesh state report, 2019–21. Statewide coverage is about 42%. Districts sampled under the NFHS frame; results are estimates and not causal measures.","source":"S37","items":[{"name":"Kanpur Nagar","score":70},{"name":"Jalaun","score":63},{"name":"Ghaziabad","score":62},{"name":"Gorakhpur","score":56},{"name":"UP statewide","score":42},{"name":"Bhadohi","score":26},{"name":"Barabanki","score":23},{"name":"Unnao","score":20}]},{"id":"youth-jobs","title":"Youth employment: a six-year comparison","unit":"PLFS usual status, % of UP residents aged 15–29, 2017–18 vs 2023–24","note":"Higher worker-population ratio and lower unemployment describe different aspects of labour use; unemployment's denominator is the labour force, not all youth. Includes subsidiary employment and unpaid household enterprises.","source":"S39","items":[{"name":"Worker-population ratio","before":28.1,"after":39},{"name":"Unemployment rate","before":16.7,"after":9.1}],"legend":["2017–18","2023–24"],"extraSources":["S48"]},{"id":"social-group-wpr","title":"Worker participation by social group in UP","unit":"PLFS usual-status worker-population ratio, %","note":"SC, ST and OBC state survey estimates from Lok Sabha reply 1118. Participation is not salaried employment or wages. Precision varies by subgroup.","source":"S40","items":[{"name":"Scheduled Castes","before":35.2,"after":43.6},{"name":"Scheduled Tribes","before":40,"after":52},{"name":"Other Backward Classes","before":34.1,"after":43}],"legend":["2017–18","2023–24"],"extraSources":[]},{"id":"homicide-counts","title":"Registered murder cases, 2017–2022","unit":"NCRB, number of FIR-registered murder cases in Uttar Pradesh","note":"2017–21 from the Ministry of Home Affairs parliamentary table; 2022 from NCRB Crime in India 2022. Counts are not conviction totals or victimisation-survey estimates. 2020 was a pandemic-disrupted year.","source":"S42","items":[{"name":"2017","score":4324},{"name":"2018","score":4018},{"name":"2019","score":3806},{"name":"2020","score":3779},{"name":"2021","score":3717},{"name":"2022","score":3491}],"legend":["Registered murder cases"],"extraSources":["S43"]},{"id":"women-offences","title":"Reported offences against women, selected years","unit":"NCRB, FIR-registered cases in Uttar Pradesh","note":"Includes 2016 pre-government baseline, 2021, 2022 and 2023. These counts are not prevalence estimates, and years are selected rather than a complete time series. In 2023 the UP rate was 58.6 per 100,000 women versus 66.2 nationally.","source":"S44","items":[{"name":"2016","score":49262},{"name":"2021","score":56083},{"name":"2022","score":65743},{"name":"2023","score":66381}],"legend":["Registered offences"],"extraSources":["S46","S49"]},{"id":"women-cybercrime","title":"Cybercrimes against women registered in UP","unit":"NCRB state administrative records, cases","note":"State police-recorded offences; an increase may reflect higher incidence, better reporting, investigation priority or a mix. 2021–23 figures are sourced to the MHA parliamentary annexure.","source":"S45","items":[{"name":"2021","score":958},{"name":"2022","score":1101},{"name":"2023","score":1463}],"legend":["Registered cases"],"extraSources":[]},{"id":"youth-neet-2025","title":"Young people outside work and education, 2025","unit":"NEET, % of people aged 15–29, PLFS 2025 usual status","note":"PLFS survey design and reference years changed in January 2025. This is a 2025 cross-sectional UP versus India comparison, NOT a continuation of the 2017–18 to 2023–24 historical trend. Screened from Appendix-A Table 57.1, page A-330.","source":"S41","items":[{"name":"Uttar Pradesh","score":29.1},{"name":"All India","score":25}],"legend":["2025 NEET share"],"extraSources":[]}],"regions":[{"name":"Agra","districts":["Agra","Firozabad","Mainpuri","Mathura"]},{"name":"Aligarh","districts":["Aligarh","Etah","Hathras","Kasganj"]},{"name":"Ayodhya","districts":["Ambedkar Nagar","Amethi","Ayodhya","Barabanki","Sultanpur"]},{"name":"Azamgarh","districts":["Azamgarh","Ballia","Mau"]},{"name":"Bareilly","districts":["Bareilly","Badaun","Pilibhit","Shahjahanpur"]},{"name":"Basti","districts":["Basti","Sant Kabir Nagar","Siddharthnagar"]},{"name":"Chitrakoot","districts":["Banda","Chitrakoot","Hamirpur","Mahoba"]},{"name":"Devipatan","districts":["Bahraich","Balrampur","Gonda","Shravasti"]},{"name":"Gorakhpur","districts":["Deoria","Gorakhpur","Kushinagar","Maharajganj"]},{"name":"Jhansi","districts":["Jalaun","Jhansi","Lalitpur"]},{"name":"Kanpur","districts":["Auraiya","Etawah","Farrukhabad","Kannauj","Kanpur Dehat","Kanpur Nagar"]},{"name":"Lucknow","districts":["Hardoi","Lakhimpur Kheri","Lucknow","Rae Bareli","Sitapur","Unnao"]},{"name":"Meerut","districts":["Baghpat","Bulandshahr","Gautam Buddha Nagar","Ghaziabad","Hapur","Meerut"]},{"name":"Mirzapur","districts":["Bhadohi","Mirzapur","Sonbhadra"]},{"name":"Moradabad","districts":["Amroha","Bijnor","Moradabad","Rampur","Sambhal"]},{"name":"Prayagraj","districts":["Fatehpur","Kaushambi","Pratapgarh","Prayagraj"]},{"name":"Saharanpur","districts":["Muzaffarnagar","Saharanpur","Shamli"]},{"name":"Varanasi","districts":["Chandauli","Ghazipur","Jaunpur","Varanasi"]}],"ratingMethod":{"title":"How the grades work","description":"These are transparent editorial judgements on the strength and direction of documented outcomes, not a mathematical government-performance index or causal estimate.","bands":[{"grade":"A","text":"Exceptional, sustained outcome improvement backed by comparable data."},{"grade":"B","text":"Substantial progress, with material shortcomings or attribution caveats."},{"grade":"C","text":"Mixed change or major execution gaps relative to stated aims."},{"grade":"D","text":"Credible evidence of sustained deterioration in a defined outcome."},{"grade":"Not rated","text":"Sources do not yet support a defensible cross-year outcome judgment."}],"rules":["A plus or minus qualifies the band; it does not imply false numerical precision.","The grade considers baseline change, remaining gap, independent verification and execution evidence.","Government announcements, budget estimates and MoUs do not count as completed outcomes.","No single overall grade is computed by averaging heterogeneous sectors.","A rating applies only to the evidence and periods quoted on its story page."]},"editorial":{"heroTitle":"The Yogi Years","heroDeck":"Nine years of Uttar Pradesh. The numbers, the outcomes, the hard questions. A source-led assessment of what improved, what did not, and what remains unresolved.","featureStatement":"The picture is neither a clean victory nor an unbroken failure.","featureDeck":"Deprivation and electricity access improved sharply. The economy expanded, but per-person output stayed relatively low. Malnutrition remained high, capital budgets were routinely underspent, and several high-profile claims still lack enough evidence for an outcome grade."}};
